            b = Gtk.Button(label=btn_text, valign=Gtk.Align.CENTER)
            b.connect("clicked", lambda *_: cb())
            row.add_suffix(b)
            lb.add(row)

        box, lb = tile_group("Configuración",
                        "Los vhosts y los hosts del sistema son del administrador: se edita una "
                        "copia y se aplica con Aplicar (pide la contraseña).")
        # (en la demostración, las rutas de siempre: las de verdad son las de su carpeta de ejemplo)
        add_row(lb, "Virtual hosts", "/opt/lampp/etc/extra/httpd-vhosts.conf" if DEMO else d["vhosts"], "Editar…",
                self.on_vhosts)
        add_row(lb, "Hosts del sistema", "/etc/hosts" if DEMO else d["hosts"], "Editar…", self.on_hosts)
        self.tools_box.pack_start(box, False, False, 0)

        if d["unregistered"]:
            box, lb = tile_group("XAMPP sin registrar",
                            "/opt/lampp es una instalación de XAMPP completa y no un enlace.")
            add_row(lb, "XAMPP en /opt/lampp", "Regístralo con un nombre para gestionarlo junto a "
                    "las demás versiones", "Registrar…", self.on_register)
            self.tools_box.pack_start(box, False, False, 0)

        box, lb = tile_group("Carpetas")
        add_row(lb, "Proyectos", "/opt/htdocs, compartida por todas las versiones", "Abrir",
                lambda: self.open_uri(GLib.filename_to_uri("/opt/htdocs")))
        # Copias de seguridad: abrirlas y borrarlas (nexum copias vaciar)
        n, size = copies_size()
        row = ActionRow("Copias de seguridad",
                        "~/nexum-backups: las copias que pides al borrar, sustituir o actualizar · %s"
                        % ("%s, %s" % (fmt_size(size), plural(n, "fichero", "ficheros")) if n else "vacía"))
        b = Gtk.Button(label="Abrir", valign=Gtk.Align.CENTER)
        b.connect("clicked", lambda *_: (os.makedirs(COPIES_DIR, mode=0o700, exist_ok=True),
                                         self.open_uri(GLib.filename_to_uri(COPIES_DIR))))
        row.add_suffix(b)
        b = Gtk.Button(label="Borrar…", valign=Gtk.Align.CENTER, sensitive=n > 0 and not self.busy)
        b.connect("clicked", lambda *_: self.on_clear_copies(n, size))
        row.add_suffix(b)
        lb.add(row)
        # Copias de los ficheros que cambia el programa por su cuenta (nexum copias-ficheros si|no)
        row = ActionRow("Copias de los ficheros que cambia el programa",
                        "El fichero de hosts, los vhosts y la configuración de los proyectos, antes de cambiarlos")
        sw = Gtk.Switch(active=os.path.exists(COPIES_FILES_FLAG), valign=Gtk.Align.CENTER, sensitive=not self.busy)
        sw.connect("notify::active", self.on_copies_files)
        row.add_suffix(sw)
        lb.add(row)
        add_row(lb, "Registros de instalaciones", "~/.nexum: logs de las instalaciones "
                "y de la ventana", "Abrir", lambda: self.open_uri(GLib.filename_to_uri(LOG_DIR)))
        # Caché de descargas de las pilas propias: lo que ocupa y vaciarla
        n, size = downloads_cache_size()
        row = ActionRow("Caché de descargas",
                        "%s: lo ya descargado de PHP, Apache, MariaDB… · %s" % (DL_CACHE_DIR, "%s, %s" % (
                            fmt_size(size), plural(n, "fichero", "ficheros")) if n else "vacía"))
        row.set_tooltip_text("El código de los componentes ya comprobado: no se descarga otra vez al reintentar, "
                             "y se usa si su web no responde.")
        b = Gtk.Button(label="Vaciar…", valign=Gtk.Align.CENTER, sensitive=n > 0 and not self.busy)
        b.connect("clicked", lambda *_: self.on_clear_downloads(size))
        row.add_suffix(b)
        lb.add(row)
        self.tools_box.pack_start(box, False, False, 0)

        self.build_error_logs(add_row)

        box, lb = tile_group("Programa", "El propio Nexum Dev Stack: sus versiones nuevas, su icono en el menú de "
                             "aplicaciones y lo que hace al cerrar la ventana.")
        add_row(lb, "Buscar una versión nueva", "Busca en GitHub (y en Descargas) una versión más "
                "nueva, firmada, y la instala", "Buscar", lambda: self.check_package(manual=True))
        add_row(lb, "Icono en el menú de aplicaciones", "Vuelve a crear el acceso «Nexum Dev Stack» "
                "si no aparece o no abre esta ventana", "Crear de nuevo",
                self.on_create_launcher)
        self.nv_tray_row(lb)
        self.tools_box.pack_start(box, False, False, 0)

